import { Request, Response } from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import * as categoryService from '../services/category.service';
import { AuthenticatedRequest } from '../middleware/auth';
import { Role } from '@prisma/client';

// 创建分类（需要管理员权限）
export const createCategory = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 检查用户角色是否为管理员
  if (req.user?.role !== Role.ADMIN) {
    res.status(403).json({
      success: false,
      error: 'Only administrators can create categories',
    });
    return;
  }

  const { name, slug, description } = req.body;

  const category = await categoryService.createCategory({
    name,
    slug,
    description,
  });

  res.status(201).json({
    success: true,
    data: category,
  });
});

// 获取单个分类详情（包括关联的博客数量）
export const getCategory = asyncHandler(async (req: Request, res: Response) => {
  const categoryId = parseInt(req.params.id as string);
  if (isNaN(categoryId)) {
    res.status(400).json({
      success: false,
      error: 'Invalid category ID',
    });
    return;
  }

  const category = await categoryService.getCategoryById(categoryId);

  res.status(200).json({
    success: true,
    data: category,
  });
});

// 获取分类列表（支持分页）
export const getCategories = asyncHandler(async (req: Request, res: Response) => {
  const page = req.query.page ? parseInt(req.query.page as string) : undefined;
  const pageSize = req.query.pageSize ? parseInt(req.query.pageSize as string) : undefined;

  const result = await categoryService.getCategories({
    page,
    pageSize,
  });

  res.status(200).json({
    success: true,
    data: result,
  });
});

// 更新分类（管理员权限）
export const updateCategory = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 检查用户角色是否为管理员
  if (req.user?.role !== Role.ADMIN) {
    res.status(403).json({
      success: false,
      error: 'Only administrators can update categories',
    });
    return;
  }

  const categoryId = parseInt(req.params.id as string);
  if (isNaN(categoryId)) {
    res.status(400).json({
      success: false,
      error: 'Invalid category ID',
    });
    return;
  }

  const { name, slug, description } = req.body;

  const updatedCategory = await categoryService.updateCategory(categoryId, {
    name,
    slug,
    description,
  });

  res.status(200).json({
    success: true,
    data: updatedCategory,
  });
});

// 删除分类（管理员权限）
export const deleteCategory = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 检查用户角色是否为管理员
  if (req.user?.role !== Role.ADMIN) {
    res.status(403).json({
      success: false,
      error: 'Only administrators can delete categories',
    });
    return;
  }

  const categoryId = parseInt(req.params.id as string);
  if (isNaN(categoryId)) {
    res.status(400).json({
      success: false,
      error: 'Invalid category ID',
    });
    return;
  }

  const result = await categoryService.deleteCategory(categoryId);

  res.status(200).json({
    success: true,
    message: result.message,
  });
});

// 获取分类下的博客列表
export const getCategoryBlogs = asyncHandler(async (req: Request, res: Response) => {
  const categoryId = parseInt(req.params.id as string);
  if (isNaN(categoryId)) {
    res.status(400).json({
      success: false,
      error: 'Invalid category ID',
    });
    return;
  }

  const page = req.query.page ? parseInt(req.query.page as string) : undefined;
  const pageSize = req.query.pageSize ? parseInt(req.query.pageSize as string) : undefined;
  const status = req.query.status as string | undefined;

  const result = await categoryService.getCategoryBlogs(categoryId, {
    page,
    pageSize,
    status,
  });

  res.status(200).json({
    success: true,
    data: result,
  });
});

