/**
 * 获取博客的评论列表（支持嵌套结构）
 */
export const getBlogComments = async (
  blogId: number,
  params: GetCommentsParams,
  currentUserId?: number
) => {
  // 验证博客是否存在
  const blog = await prisma.blog.findUnique({
    where: { id: blogId },
  });
  if (!blog) {
    throw new NotFoundError('博客不存在');
  }

  const {
    page = 1,
    limit = 10,
    sort = 'createdAt',
    order = 'desc',
    parent = false, // 默认返回所有评论
  } = params;

  // 构建查询条件
  const where: any = { blogId };

  // 如果parent为true，只查询顶级评论（parentCommentId为null）
  if (parent === true) {
    where.parentCommentId = null;
  }

  // 计算总数
  const total = await prisma.comment.count({ where });

  // 计算总页数
  const totalPages = Math.ceil(total / limit);

  // 获取评论列表
  const comments = await prisma.comment.findMany({
    where,
    skip: (page - 1) * limit,
    take: limit,
    orderBy: {
      [sort]: order,
    },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          avatar: true,
        },
      },
      blog: {
        select: {
          id: true,
          title: true,
        },
      },
      parent: {
        include: {
          user: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      },
      _count: {
        select: {
          replies: true,
        },
      },
    },
  });

  // 格式化评论数据
  const formattedComments = comments.map(comment => 
    formatComment(comment, currentUserId)
  );

  // 如果parent为true，需要构建嵌套结构
  let nestedComments = formattedComments;
  if (parent === true) {
    nestedComments = buildNestedComments(formattedComments);
  }

  return {
    comments: nestedComments,
    pagination: {
      page,
      limit,
      total,
      totalPages,
    },
  };
};

