/**
 * 格式化评论数据
 */
const formatComment = (comment: any, currentUserId?: number): NestedComment => {
  const canEdit = currentUserId ? comment.userId === currentUserId : false;
  const canDelete = canEdit; // 目前只允许作者删除，管理员权限在控制器层处理

  return {
    id: comment.id,
    content: comment.content,
    createdAt: comment.createdAt,
    updatedAt: comment.updatedAt,
    blogId: comment.blogId,
    userId: comment.userId,
    parentCommentId: comment.parentCommentId,
    user: comment.user,
    blog: comment.blog,
    parent: comment.parent ? {
      id: comment.parent.id,
      content: comment.parent.content,
      user: comment.parent.user,
    } : null,
    replyCount: comment._count.replies,
    canEdit,
    canDelete,
  };
};

/**
 * 构建嵌套评论结构
 * 将平铺的评论列表转换为树形结构
 */
const buildNestedComments = (comments: NestedComment[]): NestedComment[] => {
  // 创建评论映射表
  const commentMap = new Map<number, NestedComment>();

  // 初始化所有评论，添加replies数组
  comments.forEach(comment => {
    commentMap.set(comment.id, { ...comment, replies: [] });
  });

  // 构建树形结构
  const rootComments: NestedComment[] = [];

  comments.forEach(comment => {
    const node = commentMap.get(comment.id)!;

    if (comment.parentCommentId) {
      // 如果有父评论，添加到父评论的replies中
      const parent = commentMap.get(comment.parentCommentId);
      if (parent) {
        parent.replies!.push(node);
      } else {
        // 父评论不在当前列表中，暂时作为根评论处理
        rootComments.push(node);
      }
    } else {
      // 顶级评论
      rootComments.push(node);
    }
  });

  return rootComments;
};

/**
 * 统计博客的评论数量
 */
export const countBlogComments = async (blogId: number) => {
  const totalComments = await prisma.comment.count({
    where: { blogId },
  });

  const topLevelComments = await prisma.comment.count({
    where: { 
      blogId,
      parentCommentId: null,
    },
  });

  return {
    total: totalComments,
    topLevel: topLevelComments,
  };
};

/**
 * 统计用户的评论数量
 */
export const countUserComments = async (userId: number) => {
  const total = await prisma.comment.count({
    where: { userId },
  });

  return { total };
};

